  "completionCriteria": [
    {
      "statement": "A full loop — export diff, agent edits, import diff, tree lights up — runs end to end with single clicks",
      "evaluator": "human"
    }
  ],
  "artifacts": [
    {
      "type": "workproduct",
      "label": "AgentDiffTools.tsx — floating Export tree / Apply update buttons (diff vs current, apply, light up)",
      "uri": "web/src/components/AgentDiffTools/AgentDiffTools.tsx"
    },
    {
      "type": "workproduct",
      "label": "projectDiff.ts — compute/apply diffs + touched-set + findUnresolvedReferences (pure, tested)",
      "uri": "web/src/migrating/projectDiff.ts"
    },
    {
      "type": "workproduct",
      "label": "applyProjectDiff.ts — zome-level diff executor (create/update/delete + remap)",
      "uri": "web/src/migrating/applyProjectDiff.ts"
    },
    {
      "type": "workproduct",
      "label": "webpack.dev.js — dev-server file bridge to a fixed /tmp/acorn-clarity path",
      "uri": "web/webpack.dev.js"
