uhCkk5U1FJpj92dIg-ck2VuavFiWCUDf37g6yJ8v.description:
{
  "outcome": "Smallness is a clarity threshold, not a guess and not something a person sets by hand. A leaf's readiness to be a Small is computed from multiple signals and cached on the node, because the more complex a bottom-level item is, the less likely anyone is clear about it. Most signals are genuine gradients — how complex, how wide the agent's change, how large the review surface, how much design latitude is still open. A few are binary blockers — an unresolved unknown, no evaluable criterion — that veto readiness outright. Reaching small-enough leaves is itself part of achieving clarity.",
  "handle": "small-readiness"
}

uhCkkR4t3vRxlupZCIlBxy5NmRvJsJWWqO_uou93.description:
{
  "outcome": "A leaf's smallness readiness is a single cached value on the node — an instance of the node's computed results (the computed-results outcome b6 in branch B), not an authored field. It aggregates the readiness signals into a gradient and is rendered as the leaf's color, so one glance across the map shows which leaves are clear enough to build and which still need breakdown. Any active binary blocker clamps the gradient to not-ready regardless of the other signals.",
  "spec": "computed.smallReadiness = aggregate(gradient signals) in 0..1, clamped to 0 by any active binary blocker. Recomputed when its input fields/verdicts change and mapped to a color ramp on the leaf.",
  "completionCriteria": [
    {
      "statement": "Changing a signal recomputes the cached readiness and updates the leaf color; an active binary blocker forces the not-ready color",
      "evaluator": "executable"
    }
  ]
}

uhCkkuHrUXx822f7kBl5dAGcFJ-H81DnnuOBChCH.description:
{
  "outcome": "Every leaf shows a complexity/uncertainty estimate — the agile-style signal — as a real gradient. A higher estimate lowers readiness and, past the breakdown threshold, pushes the leaf toward decomposition; a low estimate, roughly one small unit, raises readiness.",
  "signalType": "gradient",
  "spec": "Extend smallsEstimate into a continuous contribution to computed.smallReadiness; surface the estimate and the breakdown threshold on the leaf.",
  "completionCriteria": [
    {
      "statement": "A higher complexity estimate measurably lowers the cached readiness gradient",
      "evaluator": "executable"
    }
  ]
}

uhCkktZHgbo6bj1jy7NqM1C90jKYePeqSWsFi-Hq.description:
{
  "outcome": "The estimated spread of the change a building agent would make is a gradient input to readiness: a tightly-scoped single change set reads as ready; a change spanning many unrelated areas lowers readiness and suggests a split.",
  "signalType": "gradient",
  "completionCriteria": [
    {
      "statement": "An agent's scope-spread assessment contributes proportionally to the readiness gradient",
      "evaluator": "executable"
    }
  ]
}

uhCkkQQr7WCrsBrWE2lbxmCumIZxZ7pKnK3uDyJq.description:
{
  "outcome": "The size of the review surface — how much a reviewer must hold in mind to verify the finished leaf against its criteria — is a gradient input to readiness. A leaf reviewable in one sitting reads as ready; a larger surface lowers readiness.",
  "signalType": "gradient",
  "completionCriteria": [
    {
      "statement": "A reviewer's single-sitting assessment maps onto the readiness gradient",
      "evaluator": "human"
    }
  ]
}

uhCkkAwDZnTC_mS_IlHsepprmMT2PxiW_CVaVNtK.description:
{
  "outcome": "How much design latitude remains open in the leaf's spec is a gradient input to readiness: a spec at implementation latitude with no open choices reads as ready; each unresolved design decision lowers readiness, because open design hides decomposition.",
  "signalType": "gradient",
  "spec": "Map the spec's latitude marker and its count of open decisions (branch A3) to a readiness contribution.",
  "completionCriteria": [
    {
      "statement": "Reviewer-confirmed open design decisions lower the readiness gradient",
      "evaluator": "human"
    }
  ]
}

uhCkk2tWBzplh65ATwi9kQEiLWfHaPGQq3b7_z4M.description:
{
  "outcome": "A leaf with no completion criterion concrete enough to evaluate is, by definition, not yet clear — so the absence of any evaluable criterion is a binary blocker that clamps readiness to not-ready, whatever the gradient signals say.",
  "signalType": "binary blocker",
  "completionCriteria": [
    {
      "statement": "A leaf with zero evaluable criteria shows the not-ready color until a concrete criterion is added",
      "evaluator": "human"
    }
  ]
}

uhCkk8EaY5xsVXT0iw14nBJCY3jzp-YiU9xPSgWh.description:
{
  "outcome": "An unresolved open unknown is exactly where clarity is missing, so any unresolved known-unknown on a leaf is a binary blocker: readiness is clamped to not-ready until the unknown is resolved or moved into a child outcome. (Room remains to flag suspected unknown-unknowns.)",
  "signalType": "binary blocker",
  "completionCriteria": [
    {
      "statement": "A leaf with a recorded open unknown stays not-ready until it is resolved or pushed into a child outcome",
      "evaluator": "human"
    }
  ]
}

uhCkkxI6hN4mkXCofF_W-UfzP5CzGqNq-OyAYch_.description:
{
  "outcome": "When a leaf's readiness is low or a binary blocker is active, the AI assistant proposes a concrete decomposition — child outcomes that each look more likely to be ready — for the human to approve. Reaching small-enough leaves becomes a guided, conversational step of achieving clarity.",
